package wifihaven.api.db

/**
 * The placeholder names a device row carries when its DHCP lease sent no hostname (#249), in one
 * place: ingest writes them, `DeviceRepo.renameIfAutoGenerated` matches them in SQL, and the
 * identify view (#2926) reads "is this the name the device sent, or ours?" from the same predicate.
 */
object DeviceNames {

  /** Pre-#249 placeholder, still present on old rows. */
  val LegacyPlaceholder = "unknown"

  /** `device-<last 3 octets>`, as [[generated]] writes it. A POSIX regex, used verbatim in SQL. */
  val GeneratedPattern = "^device-[0-9a-fA-F]+$"

  /**
   * Default name for a device whose DHCP lease did not provide a hostname (option 12) — e.g. iOS
   * Private Address clients. The last 3 octets of the MAC (lowercase, no separators) keeps the
   * placeholder disambiguable in the admin UI rather than collapsing every such device into the
   * literal string "unknown" (#249).
   */
  def generated(mac: String): String = {
    val hex = mac.toLowerCase.replace(":", "").replace("-", "")
    "device-" + (if hex.length >= 6 then hex.takeRight(6) else hex)
  }

  def isPlaceholder(name: String): Boolean =
    name == LegacyPlaceholder || name.matches(GeneratedPattern)
}
